function sCaseQ() {
  return CW('sql-case', {
    code: ['select', "  count(*) filter (where status='paid'),", "  sum(amount) filter (where status='paid'),", "  count(case when status='paid' then 1 end)", ['from orders;                 -- 100만 행', 'from orders;                 -- 1M rows']],
    hl: [[1, 1, 'accent'], [2, 1, 'ok'], [3, 1, 'warn'], [0, 5]],
    draw: (S) => {
      mono(S, 'r', 19.0, .5, nbs([' paid   | refunded | revenue', ' 599676 |   200091 | 150086812.94']), 1, { w: 12.4, dy: .55, c: 'sqx-g' });
      lbl(S, 'l1', 19.0, 1.8, ['FILTER는 집계마다 조건을 따로 걸어요 · 한 번 훑으면서 여러 조건을 동시에 세요', 'FILTER gives each aggregate its own condition, counting several in one scan'], 'a', 1, { w: 12.4 });
      rbars(S, 'st', 3.2, [['paid', 6.0, 'ok', '599,676'], ['pending', 2.0, 'ink-3', '200,233'], ['refunded', 2.0, 'ink-3', '200,091']], 2);
      lbl(S, 'l2', 19.0, 4.9, ['조건에 맞는 행만 집계에 들어가요 · paid 행의 금액만 더해 매출을 냈어요', 'only matching rows reach the aggregate, so revenue sums the paid rows alone'], 'g', 2, { w: 12.4 });
      T(S, 'cs', 19.0, 6.3, 'count(case … then 1 end) → 599676', 'cz-mono sqx-tiny sqx-w', 3, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.9, ['CASE는 조건마다 값을 고르는 식 · 아니면 NULL이라 count가 세지 않아요', 'CASE picks a value per condition; a non-match is NULL, which count skips'], 'w', 3, { w: 12.4 });
      mono(S, 'dz', 19.0, 8.3, ['10 / x             → division by zero', 'case when x = 0 then null else 10 / x'], 4, { w: 12.4, dy: .55, c: 'sqx-r' });
      lbl(S, 'l4', 19.0, 9.6, ['CASE는 맞는 가지만 계산해서 0으로 나누기 같은 오류를 피할 수 있어요', 'CASE evaluates only the matching branch, so it can guard against division by zero'], 'g', 4, { w: 12.4 });
      lbl(S, 'm4', 1, 7.0, ['FILTER는 SQL 표준이지만 MySQL에는 없어서, 여러 DB에서 돌려야 하면 CASE를 써요', 'FILTER is standard SQL but MySQL lacks it, so CASE is the portable choice'], 'a', 4, { w: 16.0 });
    },
    notes: [['주문 100만 건에서 상태별 개수를 한 번에 구하고 싶을 때, 조건마다 쿼리를 따로 돌리면 테이블을 여러 번 읽어요 · 집계 함수 뒤에 FILTER (WHERE …)를 붙이면 집계마다 다른 조건을 걸 수 있어서, 한 번 훑으면서 paid 599,676건과 refunded 200,091건을 함께 셌어요', 'to count orders by status across 1 million rows in one go, separate queries per condition would read the table several times; attaching FILTER (WHERE …) to an aggregate gives each one its own condition, so a single scan counted 599,676 paid and 200,091 refunded orders together'], ['FILTER는 조건에 맞는 행만 그 집계에 넣어요 · sum(amount) FILTER (WHERE status = \'paid\')는 paid 행의 금액만 더해 150,086,812.94를 냈어요 · 나머지 pending과 refunded 행은 이 합계에 들어가지 않아요', 'FILTER feeds only matching rows into that aggregate, so sum(amount) FILTER (WHERE status = \'paid\') added the paid amounts alone, giving 150,086,812.94, while the pending and refunded rows stayed out of that sum'], ['FILTER가 없던 시절에는 CASE로 같은 일을 했어요 · CASE WHEN status = \'paid\' THEN 1 END는 조건이 아니면 NULL이 되고, count는 NULL을 세지 않으므로 똑같이 599,676이 나왔어요 · sum(CASE … THEN 1 ELSE 0 END)도 흔한 형태예요', 'before FILTER existed, CASE did the same job: CASE WHEN status = \'paid\' THEN 1 END yields NULL for other rows and count skips NULLs, so it also returned 599,676, and sum(CASE … THEN 1 ELSE 0 END) is another common form'], ['CASE는 위에서부터 조건을 확인해 처음 맞는 가지의 값만 계산해요 · 그래서 10 / x는 x가 0인 행에서 division by zero 오류로 쿼리 전체가 실패했지만, CASE WHEN x = 0 THEN NULL ELSE 10 / x END는 그 행을 NULL로 넘겼어요', 'CASE checks conditions from the top and evaluates only the value of the first matching branch, so 10 / x failed the whole query with division by zero on the row where x was 0, while CASE WHEN x = 0 THEN NULL ELSE 10 / x END passed that row as NULL']],
    fin: [['FILTER = 집계마다 다른 조건', 'FILTER gives each aggregate its own condition', 'sqx-xs sqx-a'], ['CASE + NULL로 같은 일을 이식성 있게', 'CASE plus NULL does the same, portably'], ['CASE는 맞는 가지만 계산해요', 'CASE evaluates only the matching branch']],
    caps: [['조건별 집계', 'Conditional aggregates'], ['FILTER', 'FILTER'], ['CASE', 'CASE'], ['0으로 나누기 막기', 'Guarding division by zero'], ['CASE와 FILTER', 'CASE and FILTER']]
  });
}

