      lbl(S, 'l1', 19.0, 1.5, ['identity는 1씩 커지는 값 · 새 키는 늘 인덱스 맨 오른쪽 페이지에 붙어요', 'identity values grow by 1, so each new key lands on the rightmost index page'], 'a', 1, { w: 12.4 });
