      lbl(S, 'l2', 19.0, 4.0, ['UUID v4는 완전 무작위 · 새 키가 인덱스 곳곳에 흩어지며 페이지가 자주 쪼개져요', 'UUID v4 is fully random, so new keys scatter across the index and split pages often'], 'w', 2, { w: 12.4 });
      mono(S, 'tb', 19.0, 5.4, nbs(['           bigint   uuid v4', 'insert 2M  2.5 s    8.6 s', 'index      43 MB    75 MB', 'leaf fill  90 %     72 %']), 3, { w: 12.4, dy: .55, c: 'sqx-r' });
      lbl(S, 'l3', 19.0, 7.7, ['키가 2배 크고 페이지가 덜 차서 인덱스가 커지고, 쓰기가 3배 넘게 느렸어요', 'keys twice as wide and emptier pages made the index larger and writes over 3× slower'], 'r', 3, { w: 12.4 });
